import React, { useState } from 'react';
import Intro from './Intro';
import Home from './Home.js';

function App() {
  const [showIntro, setShowIntro] = useState(true);

  const handleIntroComplete = () => {
    setShowIntro(false);
  };

  return (
    <>
      {showIntro ? (
        <Intro onComplete={handleIntroComplete} />
      ) : (
        <Home />
      )}
    </>
  );
}
export default App; 